pub(super) fn append_frame(out: &mut Vec<u8>, kind: u8, flags: u8, id: u32, body: &[u8]) {
    encode_frame(kind, flags, id, body, DEFAULT_MAX_FRAME_SIZE, out).unwrap();
}

pub(super) fn request(block: &[u8], body: &[u8]) -> Vec<u8> {
    let mut wire = Vec::new();
    let head_flags = flags::END_HEADERS | if body.is_empty() { flags::END_STREAM } else { 0 };
    append_frame(&mut wire, kind::HEADERS, head_flags, 1, block);
    for (index, chunk) in body.chunks(DEFAULT_MAX_FRAME_SIZE as usize).enumerate() {
        let last = (index + 1) * DEFAULT_MAX_FRAME_SIZE as usize >= body.len();
        append_frame(&mut wire, kind::DATA, if last { flags::END_STREAM } else { 0 }, 1, chunk);
    }
    wire
}

pub(super) fn set_stream_id(wire: &mut [u8], id: u32) {
    let mut offset = 0;
    while offset < wire.len() {
        let length =
            u32::from_be_bytes([0, wire[offset], wire[offset + 1], wire[offset + 2]]) as usize;
        wire[offset + 5..offset + 9].copy_from_slice(&id.to_be_bytes());
        offset += 9 + length;
    }
}

pub(super) fn credit(bytes: usize) -> Vec<u8> {
    let mut wire = Vec::new();
    if bytes != 0 {
        append_frame(&mut wire, kind::WINDOW_UPDATE, 0, 0, &(bytes as u32).to_be_bytes());
    }
    wire
}
